def to_internal_filter(resource, filter) when is_map(filter) do
  Map.new(filter, fn {key, value} ->
    case key_string(key) do
      "and" -> {key, map_filter_list(resource, value)}
      "or" -> {key, map_filter_list(resource, value)}
